# Proper flood fill: find all 0s connected to boundary (stay 0), fill the rest (become 1)

def solve_flood_fill(grid):
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]
    queue = []

    # Add all boundary 0s to queue (these are "outside")
    for r in range(rows):
        if grid[r][0] == 0:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][cols-1] == 0:
            visited[r][cols-1] = True
    for c in range(cols):
        if grid[0][c] == 0:
            visited[0][c] = True
        if grid[rows-1][c] == 0:
            visited[rows-1][c] = True

    from collections import deque
    q = deque(queue)

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # Build output: 1 where 0s are not visited (inside), keep 2s
    output = []
    for r in range(rows):
        row_out = grid[r][:]
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                row_out[c] = 1
        output.append(row_out)

    return output

