def solve_grid(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                continue

            # Check horizontal between
            left = -1
            for cc in range(c-1, -1, -1):
                if grid[r][cc] == 2:
                    left = cc
                    break
            right = -1
            for cc in range(c+1, cols):
                if grid[r][cc] == 2:
                    right = cc
                    break

            if left >= 0 and right >= 0:
                # Horizontal gap exists
                # Check if there are vertical 2s in same columns
                has_vertical_2 = False
                for cc in range(left+1, right):
                    for rr in range(rows):
                        if grid[rr][cc] == 2:
                            has_vertical_2 = True
                            break
                    if has_vertical_2:
                        break

                if not has_vertical_2:
                    output[r][c] = 1
                    continue

            # Check vertical between
            top = -1
            for rr in range(r-1, -1, -1):
                if grid[rr][c] == 2:
                    top = rr
                    break
            bottom = -1
            for rr in range(r+1, rows):
                if grid[rr][c] == 2:
                    bottom = rr
                    break

            if top >= 0 and bottom >= 0:
                # Vertical gap exists
                # Check if there are horizontal 2s in same rows
                has_horizontal_2 = False
                for rr in range(top+1, bottom):
                    for cc in range(cols):
                        if grid[rr][cc] == 2:
                            has_horizontal_2 = True
                            break
                    if has_horizontal_2:
