# Let me try the simplest rule: gaps bounded by 2s on BOTH sides of the same axis
# A horizontal run fills if bounded horizontally by 2s AND NO 2s bound it vertically
# A vertical run fills if bounded vertically by 2s AND NO 2s bound it horizontally

def solve_rule2(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # Horizontal runs: fill if bounded by 2s and the bounding 2s don't connect vertically
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                continue
            row = grid[r]
            # Check if this 0 is between 2s horizontally
            left = c - 1
            while left >= 0 and row[left] == 0:
                left -= 1
            right = c + 1
            while right < cols and row[right] == 0:
                right += 1

            if left >= 0 and row[left] == 2 and right < cols and row[right] == 2:
                # Find the two bounding 2s
                if check_non_vertical_run(grid, r, left, right):
                    result[r][c] = 1

    # Vertical runs: fill if bounded by 2s and the bounding 2s don't connect horizontally
    for r in range(rows):
        for c in range(cols):
            if result[r][c] == 1:
                continue
            if grid[r][c] == 2:
                continue
            col = [grid[rr][c] for rr in range(rows)]
            top = r - 1
            while top >= 0 and col[top] == 0:
                top -= 1
            bottom = r + 1
            while bottom < rows and col[bottom] == 0:
                bottom += 1

            if top >= 0 and col[top] == 2 and bottom < rows and col[bottom] == 2:
                if check_non_horizontal_run(grid, top, bottom, c):
                    result[r][c] = 1

    return result

def check_non_vertical_run(grid, r, left, right):
    """Check if horizontal run at row r, cols left to right doesn't have vertical 2s on the boundary"""
    for col_idx in range(left + 1, right):
        # Check if any 2 is above or below this column in the run
        for rr in range(r - 1, -1, -1):
            if grid[rr][col_idx] == 2:
                return False
        for rr in range(r + 1, len(grid)):
            if grid[rr][col_idx] == 2:
                return False
    return True

def check_non_horizontal_run(grid, top, bottom, c):
    """Check if vertical run at col c, rows top to bottom doesn't have horizontal 2s on the boundary"""
    for row_idx in range(top + 1, bottom):
        for cc in range(c - 1, -1, -1):
            if grid[row_idx][cc] == 2:
                return False
        for cc in range(c + 1, len(grid[0])):
            if grid[row_idx][cc] == 2:
